- name: Verify the single terminal receipt
  id: verify
  if: ${{ needs.apply.result == 'success' }}
  shell: bash
  run: |
    node --input-type=module <<'NODE'
    import fs from "node:fs";
    import {
      createV4ReleaseInvocation,
      createV4ReleaseReceipt,
      createV4ReleaseTransaction,
    } from "./.buildchain/runtime/packages/core/v4-release-invocation.js";
    const base = ".buildchain/evidence/release-tail";
    const invocation = JSON.parse(fs.readFileSync(`${base}/release-invocation.json`, "utf8"));
    const transaction = JSON.parse(fs.readFileSync(`${base}/release-transaction.json`, "utf8"));
    const storedReceipt = JSON.parse(fs.readFileSync(`${base}/release-receipt.json`, "utf8"));
    const invocationProjection = createV4ReleaseInvocation(invocation);
    const transactionProjection = createV4ReleaseTransaction({
      invocationRoot: transaction.invocationRoot,
      publisherRoot: transaction.publisherRoot,
      runtimeRoot: transaction.runtimeRoot,
      providerRoot: transaction.providerRoot,
      parentRoot: transaction.parentRoot,
    });
    const { receiptRoot, ...receipt } = storedReceipt;
    const receiptProjection = createV4ReleaseReceipt(receipt);
    if (transaction.invocationRoot !== invocationProjection.roots.invocationRoot ||
        transaction.transactionRoot !== transactionProjection.transactionRoot ||
        receipt.transactionRoot !== transactionProjection.transactionRoot ||
        receiptProjection.receiptRoot !== receiptRoot || receipt.outcome !== "complete") {
      throw new Error("terminal ReleaseReceipt lineage does not verify");
    }
    fs.appendFileSync(process.env.GITHUB_OUTPUT,
      `receipt-json=${JSON.stringify(storedReceipt)}\nreceipt-root=${receiptRoot}\nstatus=complete\n`);
    NODE

- name: Record non-terminal projection state
