- name: Verify the single terminal receipt
  id: verify
  env:
    CANDIDATE_SHA: ${{ needs.qualify.outputs.requested-sha }}
  if: ${{ needs.qualify.outputs.action == 'promote' && !inputs.dry-run }}
  shell: bash
  run: |
    node --input-type=module <<'NODE'
    import fs from "node:fs";
    const { readApplyDocuments, verifyPublicationSettlement } = await import("./.buildchain/runtime/scripts/v4-publication-settlement.mjs");
    const documents = readApplyDocuments(".buildchain/evidence");
    verifyPublicationSettlement(documents, {
      repository: process.env.GITHUB_REPOSITORY,
      candidateSha: process.env.CANDIDATE_SHA,
      tag: documents.invocation.target.tag,
      sourceSha: documents.product.publication.releaseSha,
    });
    const storedReceipt = documents.receipt;
    const receiptRoot = storedReceipt.receiptRoot;
    fs.appendFileSync(process.env.GITHUB_OUTPUT,
      `receipt-json=${JSON.stringify(storedReceipt)}\nreceipt-root=${receiptRoot}\nstatus=complete\n`);
    NODE

- name: Record non-terminal projection state
  id: projection-state
